on conflict (symbol, effective_from, mapping_version)
do update set
    sector_code = excluded.sector_code,
    sector_name = excluded.sector_name,
    sector_benchmark_symbol = excluded.sector_benchmark_symbol,
    effective_to = excluded.effective_to,
    source = excluded.source,
    mapping_status = excluded.mapping_status,
    confidence_status = excluded.confidence_status,
    metadata_json = excluded.metadata_json,
    updated_at = now();

-- Verification
select
    mapping_version,
    mapping_status,
    count(*) as rows,
    count(*) filter (where sector_benchmark_symbol is null) as no_sector_benchmark
from public.pms_sector_mappings
where mapping_version = 'PMS-SECTOR-MAP-0.1'
group by mapping_version, mapping_status
order by mapping_status;
